fact = [0] * 70
fact[0] = 1
for i in range(1, 70, 1):
	fact[i] = i * fact[i - 1]
ans = [1]
for i in range(2, 70, 1):
	ans.append(fact[i] // (fact[i // 2] * fact[i - i // 2]))
t = int(input())
for z in range(t):
	n = int(input())
	for i in range(70):
		if ans[i] >= n:
			print(i + 1)
			break
